package main

import (
	"fmt"
	"net/http"
)

const css = `
:root{--bg:#ffffff;--paper:#ffffff;--soft:#f7f7f5;--ink:#181818;--muted:#6f6f6f;--line:#deded8;--accent:#ffd84d;--pink:#ff9bd5;--cyan:#bcefff;--green:#bdf2c1}
body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.shell{min-height:100vh;display:flex}.side{position:fixed;inset:0 auto 0 0;width:245px;padding:20px 16px;border-right:1px solid var(--line);background:#fff;z-index:5}
.brand{display:flex;align-items:center;gap:10px;padding:7px 8px 24px;font-size:20px;font-weight:850}.logo{width:34px;height:34px;border:2px solid var(--ink);background:var(--accent);color:var(--ink);display:grid;place-items:center;font-weight:950;box-shadow:3px 3px 0 var(--ink)}
.nav{display:grid;gap:7px}.nav a{display:flex;gap:11px;align-items:center;padding:11px 12px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--ink);text-decoration:none;font-weight:750;transition:.15s}.nav a:hover,.nav .on{background:var(--soft);border-color:#c8c8c0;transform:translateX(2px);box-shadow:3px 3px 0 #e8e8e2}.bottom{position:absolute;bottom:18px;left:16px;right:16px;color:var(--muted);font-size:12px}
.main{margin-left:245px;max-width:1250px;width:100%;padding:34px 38px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px}.eyebrow{color:#8a7000;font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.title{margin:5px 0 4px;font-size:30px;letter-spacing:-.035em}.muted{color:var(--muted)}.actions{display:flex;gap:9px}.btn{border:1px solid var(--ink);background:#fff;color:var(--ink);padding:10px 14px;border-radius:9px;text-decoration:none;font-weight:800;box-shadow:3px 3px 0 #deded8;cursor:pointer}.btn:hover{transform:translate(1px,1px);box-shadow:2px 2px 0 #deded8}.btn.primary{background:var(--accent)}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-top:28px}.card{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:19px;box-shadow:4px 4px 0 #f0f0ec}.label{color:var(--muted);font-size:12px;font-weight:700}.value{font-size:27px;font-weight:850;margin-top:9px;letter-spacing:-.03em}.status{display:inline-flex;align-items:center;gap:7px}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);border:1px solid #70b875}
.section{margin-top:20px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.section h2{font-size:15px;margin:0;font-weight:800}.table{padding:4px 18px}.row{display:flex;justify-content:space-between;gap:18px;padding:15px 0;border-bottom:1px solid var(--line)}.row:last-child{border:0}.pill{padding:5px 8px;border-radius:7px;background:var(--green);border:1px solid #8dce91;font-size:11px;font-weight:800}
.endpoint-url{margin-top:7px;font:700 16px ui-monospace,SFMono-Regular,Menlo,monospace;word-break:break-all}.curl-box{margin-top:16px;border:1px solid var(--ink);border-radius:10px;overflow:hidden;background:#171717;color:#fff}.curl-head{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-bottom:1px solid #333;font-size:12px;font-weight:800}.curl-head .small-btn{padding:5px 8px;background:#fff;color:#111;box-shadow:none}.curl-box pre{margin:0;padding:14px;white-space:pre-wrap;word-break:break-word;font:12px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace}.console-card{border:1px solid var(--ink);border-radius:12px;background:#171717;color:#eee;overflow:hidden;box-shadow:4px 4px 0 #deded8}.console-head{padding:10px 13px;border-bottom:1px solid #333;font:700 12px ui-monospace,SFMono-Regular,Menlo,monospace}.console-head span{float:right;color:#bdf2c1}.console-body{min-height:170px;max-height:280px;overflow:auto;padding:13px;font:12px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace}.log-line{padding:3px 0}.log-ok{color:#bdf2c1}.log-bad{color:#ff9bd5}.@media(max-width:820px){.side{position:static;width:100%;height:auto;border-right:0;border-bottom:1px solid var(--line);padding:12px}.shell{display:block}.brand{padding:4px 6px 12px}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.bottom{display:none}.main{margin-left:0;padding:22px 15px}.grid{grid-template-columns:1fr}.top{align-items:flex-start}.actions{display:none}}

`

func dashboard(w http.ResponseWriter){
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	html := `<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='theme-color' content='#07070a'><title>Axy Router — SaaS Gateway</title><style>` + css + `</style></head><body><div class='shell'><aside class='side'><div class='brand'><span class='logo'>A</span>Axy Router</div><nav class='nav'><a class='on' href='/'>⌂ <span>Overview</span></a><a href='/providers'>◆ <span>Providers</span></a><a href='/'>◇ <span>Models</span></a><a href='/'>⌘ <span>API Keys</span></a><a href='/'>≡ <span>Logs</span></a><a href='/'>⚙ <span>Settings</span></a></nav><div class='bottom'>SaaS Gateway · v1.0</div></aside><main class='main'><div class='top'><div><div class='eyebrow'>Control Center</div><h1 class='title'>Good to see you.</h1><div class='muted'>Manage your AI gateway from one clean workspace.</div></div><div class='actions'><a class='btn' href='/api/health'>Health</a><form method='post' action='/logout'><button class='btn'>Logout</button></form></div></div><div class='grid'><div class='card'><div class='label'>Gateway status</div><div class='value status'><i class='dot'></i>Online</div></div><div class='card'><div class='label'>Connected providers</div><div class='value' id='providers'>—</div></div><div class='card'><div class='label'>API endpoint</div><div class='value'>Ready</div></div></div><section class='section'><div class='section-head'><h2>API endpoint</h2><span class='muted'>OpenAI-compatible</span></div><div class='card'><div class='label'>Base URL</div><div class='endpoint-url' id='endpointUrl'></div><div class='curl-box'><div class='curl-head'><span>cURL</span><button class='small-btn' onclick='copyCurl()'>Copy</button></div><pre id='curlExample'></pre></div></div></section><section class='section'><div class='section-head'><h2>Request console</h2><span class='muted'>Outbound routes only</span></div><div class='console-card'><div class='console-head'>axy-router <span>● live</span></div><div id='console' class='console-body'>Waiting for requests…</div></div></section><section class='section'><div class='section-head'><h2>Provider overview</h2><span class='muted'>Live configuration</span></div><div class='card table'><div id='list' class='muted'>Loading providers…</div></div></section></main></div><script>const origin=location.origin;const curl='curl '+origin+'/v1/chat/completions -H "Content-Type: application/json" -H "Authorization: Bearer YOUR_API_KEY" -d \'{"model":"YOUR_MODEL","messages":[{"role":"user","content":"Hello"}]}\'';document.getElementById('endpointUrl').textContent=origin+'/v1';document.getElementById('curlExample').textContent=curl;function copyCurl(){navigator.clipboard?.writeText(curl)}fetch('/api/providers').then(r=>r.json()).then(x=>{document.querySelector('#providers').textContent=x.providers.length;document.querySelector('#list').innerHTML=x.providers.length?x.providers.map(p=>'<div class="row"><div><b>'+p.name+'</b><div class="muted">'+p.base_url+'</div></div><div><span class="pill">'+(p.enabled?'Enabled':'Disabled')+'</span><div class="muted" style="margin-top:5px;text-align:right">'+p.model+'</div></div></div>').join(''):'No providers configured yet.'}).catch(()=>document.querySelector('#list').textContent='Unable to load providers.');function logs(){fetch('/api/logs').then(r=>r.json()).then(x=>{const el=document.getElementById('console');el.innerHTML=x.logs.length?x.logs.map(l=>'<div class="log-line '+(l.status>=200&&l.status<400?'log-ok':'log-bad')+'">['+l.time+'] '+l.method+' '+l.path+' → '+l.status+' · '+l.duration+'</div>').join(''):'Waiting for requests…'}).catch(()=>{})}logs();setInterval(logs,2000)</script></body></html>`
	fmt.Fprint(w, html)
}

func(s *Server)usagePage(w http.ResponseWriter,r *http.Request){
	if !s.authed(r){http.Redirect(w,r,"/login",302);return}
	w.Header().Set("Content-Type","text/html; charset=utf-8")
	html := `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Axy Router — Usage</title><style>` + css + `</style></head><body><div class="shell"><aside class="side"><div class="brand"><span class="logo">A</span>Axy Router</div><nav class="nav"><a href="/">▣ <span>Overview</span></a><a href="/providers">◆ <span>Providers</span></a><a class="on" href="/usage">◇ <span>Usage</span></a><a href="/">⌘ <span>API Keys</span></a><a href="/">≡ <span>Logs</span></a><a href="/">⚙ <span>Settings</span></a></nav><div class="bottom">Axy Gateway · v1.0</div></aside><main class="main"><div class="top"><div><div class="eyebrow">Usage & Routing</div><h1 class="title">Flow Canvas</h1><div class="muted">Visualize request flow through Axy Router.</div></div><div class="actions"><a class="btn" href="/providers">Providers</a></div></div><div class="flow-wrap"><div class="flow-toolbar"><div><b>Node-Based UI</b><div class="muted">Flow-Based Canvas · outbound routing</div></div><span class="pill">Live topology</span></div><div class="flow-canvas"><svg class="flow-svg" viewBox="0 0 1000 540" preserveAspectRatio="none"><path class="flow-line active" d="M225 270 C285 270 315 270 380 270"/><circle class="flow-handle" cx="225" cy="270" r="5"/><circle class="flow-handle" cx="380" cy="270" r="5"/><path class="flow-line" d="M570 270 C650 270 700 155 820 155"/><path class="flow-line" d="M570 270 C650 270 700 325 820 325"/><path class="flow-line" d="M570 270 C650 270 700 495 820 495"/><circle class="flow-handle" cx="570" cy="270" r="5"/><circle class="flow-handle" cx="820" cy="155" r="5"/><circle class="flow-handle" cx="820" cy="325" r="5"/><circle class="flow-handle" cx="820" cy="495" r="5"/></svg><div class="flow-node gateway"><div class="node-title"><span class="flow-dot"></span>Axy Gateway</div><div class="node-meta">/v1/chat/completions</div></div><div class="flow-node router"><div class="node-title">Router</div><div class="node-meta">Model selection · routing</div></div><div class="flow-node provider1"><div class="node-title">Provider 01</div><div class="node-meta">OpenAI compatible</div></div><div class="flow-node provider2"><div class="node-title">Provider 02</div><div class="node-meta">Anthropic compatible</div></div><div class="flow-node provider3"><div class="node-title">Provider 03</div><div class="node-meta">Custom endpoint</div></div></div></div></main></div></body></html>`
	fmt.Fprint(w,html)
}
func(s *Server)providerPage(w http.ResponseWriter,r *http.Request){
	if !s.authed(r){http.Redirect(w,r,"/login",302);return}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	html := `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Axy Router — Providers</title><style>` + css + `
.provider-wrap{display:grid;gap:24px}.provider-config-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.provider-add-area{background:#fff;border:1px solid var(--line);border-radius:13px;padding:18px;box-shadow:4px 4px 0 #f0f0ec}.provider-add-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.provider-add-card{display:flex;align-items:center;gap:11px;text-align:left;padding:13px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--ink);cursor:pointer;min-width:0}.provider-add-card:hover{border-color:var(--ink);box-shadow:3px 3px 0 #deded8;transform:translate(-1px,-1px)}.provider-add-card span:nth-child(2){display:grid;gap:2px;min-width:0}.provider-add-card b{font-size:13px}.provider-add-card small{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.provider-add-card strong{margin-left:auto}.preset-icon{width:32px;height:32px;display:grid;place-items:center;flex:none;border:1px solid var(--ink);border-radius:8px;background:var(--accent);font-weight:950}@media(max-width:900px){.provider-add-grid{grid-template-columns:repeat(2,1fr)}}.provider-toolbar{display:flex;justify-content:space-between;align-items:flex-end;gap:16px}.providers-section{display:grid;gap:12px}.provider-tabs{display:flex;gap:7px;overflow:auto}.tab{padding:8px 12px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);font:inherit;font-weight:800;white-space:nowrap;cursor:pointer}.tab.active{background:var(--ink);color:#fff;border-color:var(--ink)}
.connection-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.connection{background:#fff;border:1px solid var(--line);border-radius:13px;padding:18px;box-shadow:4px 4px 0 #f0f0ec}.connection-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.provider-icon{width:42px;height:42px;border:1px solid var(--ink);border-radius:10px;background:var(--accent);display:grid;place-items:center;font-weight:950;font-size:18px;box-shadow:3px 3px 0 var(--ink)}.provider-name{font-size:16px;font-weight:900;margin-top:2px}.provider-type{font-size:12px;color:var(--muted);margin-top:3px}.connection-meta{display:grid;gap:8px;margin:16px 0}.meta-line{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid #eee}.meta-line:last-child{border-bottom:0}.meta-key{color:var(--muted);font-size:12px}.meta-value{font-weight:750;text-align:right;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.provider-actions{display:flex;gap:8px}.small-btn{border:1px solid var(--ink);background:#fff;color:var(--ink);padding:8px 10px;border-radius:8px;font-weight:800;cursor:pointer}.small-btn.primary{background:var(--accent)}.empty{padding:34px;text-align:center;border:1px dashed #cfcfc8;border-radius:12px;color:var(--muted);background:#fff}.add-panel{display:none;background:#fff;border:1px solid var(--line);border-radius:13px;padding:18px;box-shadow:4px 4px 0 #f0f0ec}.add-panel.open{display:block}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form input,.form select{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:9px;background:#fff;color:#111;font:inherit;box-sizing:border-box}.form .full{grid-column:1/-1}.form button{padding:11px 15px;border:1px solid var(--ink);border-radius:9px;background:var(--accent);color:#111;font-weight:900;box-shadow:3px 3px 0 #deded8;cursor:pointer}.section-label{font-size:13px;font-weight:900;margin-bottom:10px}.secret{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}
@media(max-width:820px){.connection-grid{grid-template-columns:1fr}.form{grid-template-columns:1fr}.form .full{grid-column:auto}.provider-toolbar{align-items:flex-start;flex-direction:column}.provider-actions{flex-wrap:wrap}}
.flow-wrap{margin-top:24px}.flow-toolbar{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:12px}.flow-canvas{position:relative;min-height:540px;overflow:hidden;border:1px solid var(--line);border-radius:14px;background-color:#fafaf8;background-image:radial-gradient(#d8d8d2 1px,transparent 1px);background-size:22px 22px;box-shadow:4px 4px 0 #f0f0ec}.flow-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}.flow-line{fill:none;stroke:#8b8b84;stroke-width:2.5;stroke-linecap:round}.flow-line.active{stroke:#181818;stroke-width:3}.flow-handle{fill:#fff;stroke:#181818;stroke-width:2}.flow-node{position:absolute;width:190px;background:#fff;border:1px solid var(--ink);border-radius:11px;padding:13px;box-shadow:4px 4px 0 #deded8}.flow-node .node-title{font-weight:900}.flow-node .node-meta{font-size:11px;color:var(--muted);margin-top:5px}.gateway{left:4%;top:38%}.router{left:38%;top:38%;background:var(--accent)}.provider1{right:5%;top:15%}.provider2{right:5%;top:39%}.provider3{right:5%;top:63%}.flow-dot{width:8px;height:8px;border-radius:50%;display:inline-block;background:var(--green);border:1px solid #70b875;margin-right:6px}@media(max-width:820px){.flow-canvas{min-height:760px}.flow-node{left:18px!important;right:auto!important;width:calc(100% - 60px)}.gateway{top:5%}.router{top:29%}.provider1{top:53%}.provider2{top:67%}.provider3{top:81%}}</style></head><body><div class="shell"><aside class="side"><div class="brand"><span class="logo">A</span>Axy Router</div><nav class="nav"><a href="/">▣ <span>Overview</span></a><a class="on" href="/providers">◆ <span>Providers</span></a><a href="/usage">◇ <span>Usage</span></a><a href="/">⌘ <span>API Keys</span></a><a href="/">≡ <span>Logs</span></a><a href="/">⚙ <span>Settings</span></a></nav><div class="bottom">Axy Gateway · v1.0</div></aside><main class="main"><div class="top"><div><div class="eyebrow">Connections</div><h1 class="title">Providers</h1><div class="muted">Connect API providers and manage the backends used by Axy Router.</div></div><div class="actions"><a class="btn" href="/">← Overview</a></div></div><div class="provider-wrap" style="margin-top:24px"><div class="provider-toolbar"><div class="provider-tabs"><button class="tab active" type="button" onclick="showAdd('all',this)">All</button><button class="tab" type="button" onclick="showAdd('apikey',this)">API Key</button><button class="tab" type="button" onclick="showAdd('oauth',this)">OAuth</button><button class="tab" type="button" onclick="showAdd('free',this)">Free</button><button class="tab" type="button" onclick="showAdd('custom',this)">Custom</button></div></div><div class="provider-add-area" id="customArea"><div class="section-label">Custom</div><div class="provider-add-grid"><button class="provider-add-card" type="button" onclick="setPreset('custom-openai')"><span class="preset-icon">O</span><span><b>OpenAI Compatible</b><small>Custom Base URL + API Key</small></span><strong>→</strong></button><button class="provider-add-card" type="button" onclick="setPreset('custom-anthropic')"><span class="preset-icon">A</span><span><b>Anthropic Compatible</b><small>Custom Base URL + API Key</small></span><strong>→</strong></button></div></div><div class="provider-add-area" id="apiKeyArea"><div class="section-label">API Key providers</div><div class="provider-add-grid"><button class="provider-add-card" type="button" onclick="setPreset('openai')"><span class="preset-icon">O</span><span><b>OpenAI</b><small>API Key</small></span><strong>→</strong></button><button class="provider-add-card" type="button" onclick="setPreset('anthropic')"><span class="preset-icon">A</span><span><b>Anthropic</b><small>API Key</small></span><strong>→</strong></button><button class="provider-add-card" type="button" onclick="setPreset('openrouter')"><span class="preset-icon">R</span><span><b>OpenRouter</b><small>API Key</small></span><strong>→</strong></button><button class="provider-add-card" type="button" onclick="setPreset('deepseek')"><span class="preset-icon">D</span><span><b>DeepSeek</b><small>API Key</small></span><strong>→</strong></button><button class="provider-add-card" type="button" onclick="setPreset('groq')"><span class="preset-icon">G</span><span><b>Groq</b><small>API Key</small></span><strong>→</strong></button></div></div><div class="add-panel" id="panel"><div class="section-label" id="panelTitle">OpenAI Compatible configuration</div><form class="form" id="f"><input name="name" id="nameField" placeholder="OpenAI connection name" required><input type="hidden" name="api_type" id="apiType" value="openai"><input name="model" placeholder="Model ID (e.g. gpt-5)" required><input class="full" name="base_url" id="baseUrl" placeholder="https://api.openai.com/v1" required><input class="full" name="api_key" type="password" placeholder="OpenAI API key" required><div class="full" id="typeHint" style="color:var(--muted);font-size:12px">OpenAI-compatible: /chat/completions + Bearer API key.</div><button class="full" id="saveBtn">Save OpenAI configuration</button></form></div><section class="providers-section"><div class="section-head"><div><h2>Connected providers</h2><div class="muted" id="count" style="margin-top:4px">Loading…</div></div></div><div class="connection-grid" id="list"></div></section></div></main></div><script>
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function icon(n){return esc((n||"A").trim().charAt(0).toUpperCase())}
function load(){fetch("/api/providers").then(r=>r.json()).then(x=>{document.getElementById("count").textContent=x.providers.length+" configured";const list=document.getElementById("list");if(!x.providers.length){list.innerHTML='<div class="empty" style="grid-column:1/-1"><b>No providers connected</b><div style="margin-top:6px">Add your first OpenAI-compatible backend to get started.</div></div>';return}list.innerHTML=x.providers.map(p=>'<article class="connection"><div class="connection-head"><div style="display:flex;gap:12px;align-items:center"><div class="provider-icon">'+icon(p.name)+'</div><div><div class="provider-name">'+esc(p.name)+'</div><div class="provider-type">'+(p.api_type==='anthropic'?'API Key · Anthropic compatible':'API Key · OpenAI compatible')+'</div></div></div><span class="pill">'+(p.enabled?'Connected':'Disabled')+'</span></div><div class="connection-meta"><div class="meta-line"><span class="meta-key">Base URL</span><span class="meta-value">'+esc(p.base_url)+'</span></div><div class="meta-line"><span class="meta-key">Model</span><span class="meta-value">'+esc(p.model)+'</span></div><div class="meta-line"><span class="meta-key">API key</span><span class="meta-value secret">••••••••</span></div></div><div class="provider-actions"><button class="small-btn primary" type="button" onclick="testProvider('+p.id+',this)">Test</button><button class="small-btn" type="button" onclick="alert('Edit provider akan ditambahkan berikutnya.')">Edit</button></div></article>').join("")}).catch(()=>document.getElementById("list").innerHTML='<div class="empty">Unable to load providers.</div>')}
function showAdd(type,btn){document.querySelectorAll(".provider-tabs .tab").forEach(x=>x.classList.remove("active"));btn.classList.add("active");document.getElementById("apiKeyArea").style.display=(type==="custom"?"none":"block");document.getElementById("customArea").style.display=(type==="custom"?"block":"none");if(type==="oauth"||type==="free"){document.getElementById("apiKeyArea").style.display="block";document.getElementById("apiKeyArea").querySelector(".section-label").textContent=type==="oauth"?"OAuth providers":"Free providers";document.getElementById("apiKeyArea").querySelector(".provider-add-grid").innerHTML='<div class="empty" style="grid-column:1/-1">Coming soon</div>'}else if(type==="apikey"){document.getElementById("apiKeyArea").querySelector(".section-label").textContent="API Key providers"}else if(type==="all"){document.getElementById("apiKeyArea").querySelector(".section-label").textContent="Add API Key provider";document.getElementById("customArea").style.display="block"}}
function setPreset(p){if(p==="deepseek"){setConfig("openai");document.getElementById("nameField").value="DeepSeek";document.getElementById("baseUrl").value="https://api.deepseek.com/v1";return}if(p==="groq"){setConfig("openai");document.getElementById("nameField").value="Groq";document.getElementById("baseUrl").value="https://api.groq.com/openai/v1";return}if(p==="openrouter"){setConfig("openai");document.getElementById("nameField").value="OpenRouter";document.getElementById("baseUrl").value="https://openrouter.ai/api/v1";return}if(p==="custom-openai"){setConfig("openai");document.getElementById("nameField").value="";document.getElementById("baseUrl").value="";document.getElementById("panelTitle").textContent="Custom OpenAI Compatible configuration";return}if(p==="custom-anthropic"){setConfig("anthropic");document.getElementById("nameField").value="";document.getElementById("baseUrl").value="";document.getElementById("panelTitle").textContent="Custom Anthropic Compatible configuration";return}if(p==="custom"){setConfig("openai");document.getElementById("nameField").value="";document.getElementById("baseUrl").value="";document.getElementById("panelTitle").textContent="Custom provider configuration";return}setConfig(p);}
function setConfig(type){const a=type==="anthropic";document.getElementById("apiType").value=type;document.getElementById("panel").classList.add("open");document.getElementById("panelTitle").textContent=a?"Anthropic Compatible configuration":"OpenAI Compatible configuration";document.getElementById("nameField").placeholder=a?"Anthropic connection name":"OpenAI connection name";document.getElementById("baseUrl").placeholder=a?"https://api.anthropic.com/v1":"https://api.openai.com/v1";document.querySelector('[name="api_key"]').placeholder=a?"Anthropic API key":"OpenAI API key";document.getElementById("typeHint").textContent=a?"Anthropic-compatible: /messages + x-api-key + anthropic-version.":"OpenAI-compatible: /chat/completions + Bearer API key.";document.getElementById("saveBtn").textContent=a?"Save Anthropic configuration":"Save OpenAI configuration";}
async function testProvider(id,btn){const old=btn.textContent;btn.textContent="Testing…";btn.disabled=true;try{const r=await fetch("/api/providers/test",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id})});const x=await r.json();alert(r.ok&&x.ok?"Connection OK · "+x.provider+" · "+x.model:(x.error||"Connection failed"))}catch(e){alert("Connection failed")}finally{btn.textContent=old;btn.disabled=false}}
document.getElementById("f").onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));let r=await fetch("/api/providers",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)});if(r.ok){e.target.reset();document.getElementById("panel").classList.remove("open");load()}else{let x=await r.json().catch(()=>({}));alert(x.error||"Failed to save provider")}};
load();
</script></body></html>`
	fmt.Fprint(w,html)
}

func loginPage(w http.ResponseWriter, msg string){
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	html := fmt.Sprintf(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Axy Router — Sign in</title><style>`+css+`.login{min-height:100vh;display:grid;place-items:center;padding:20px}.login-card{width:min(410px,100%);padding:30px;border:1px solid var(--line);border-radius:20px;background:rgba(16,17,22,.92)}.login-card h1{margin:0;font-size:25px}.login-card p{color:var(--muted)}input,button{width:100%;font:inherit}input{padding:13px 14px;border-radius:11px;border:1px solid var(--line);background:#090a0e;color:#fff;outline:none}button{margin-top:10px;padding:13px;border:0;border-radius:11px;background:var(--accent);color:#fff;font-weight:750;cursor:pointer}.error{color:#ff7777!important;font-size:13px}</style></head><body><main class="login"><form class="login-card" method="post"><div class="brand" style="padding:0 0 20px"><span class="logo">A</span>Axy Router</div><h1>Welcome back</h1><p>Enter your admin PIN to access the gateway.</p><input name="pin" type="password" inputmode="numeric" maxlength="12" autofocus placeholder="Admin PIN"><button>Sign in</button><p class="error">%s</p></form></main></body></html>`, msg)
	fmt.Fprint(w, html)
}
